private static Map<String,Object> ownedState(ApexPages.StandardSetController sc,Set<Id> ids,String primary,String secondary){
 Map<String,Object> state=new Map<String,Object>();String filter=sc.getFilterId();
 state.put('filterKind',filter==null?'null':filter==primary?'primary':filter==secondary?'secondary':'other');
 state.put('filterShape',filter==null?null:filter.length()+':'+filter.substring(0,Math.min(3,filter.length())));
 state.put('page',sc.getPageNumber());state.put('size',sc.getPageSize());
 List<String> owned=new List<String>();for(SObject row:sc.getRecords())if(ids.contains(row.Id))owned.add(String.valueOf(row.get('Name')));
 List<String> selected=new List<String>();for(SObject row:sc.getSelected())if(ids.contains(row.Id))selected.add(String.valueOf(row.get('Name')));
 state.put('owned',owned);state.put('selected',selected);return state;
}
}

